<div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>الاسم</th><th>المسمى الوظيفي</th><th>التواصل</th><th>الأساسية</th><?php if($canEdit):?><th>الإجراءات</th><?php endif;?></tr></thead><tbody>
<?php if($contacts===[]):?><tr><td colspan="5" class="text-center text-secondary py-4">لا توجد جهات اتصال.</td></tr><?php endif;?>
<?php foreach($contacts as $contact):?>
<?php $payload=json_encode(['id'=>(int)$contact['id'],'name'=>$contact['name'],'job_title'=>$contact['job_title'],'phone'=>$contact['phone'],'mobile'=>$contact['mobile'],'email'=>$contact['email'],'is_primary'=>(bool)$contact['is_primary'],'notes'=>$contact['notes']],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?>
<tr><td><?=e($contact['name'])?></td><td><?=e($contact['job_title']?:'—')?></td><td><?=e($contact['mobile']?:($contact['phone']?:($contact['email']?:'—')))?></td><td><?=$contact['is_primary']?'<span class="badge bg-primary-lt">أساسية</span>':'—'?></td><?php if($canEdit):?><td><div class="btn-list flex-nowrap"><button class="btn btn-sm js-edit-vendor-contact" type="button" data-contact="<?=e((string)$payload)?>">تعديل</button><?php if(!$contact['is_primary']):?><button class="btn btn-sm js-primary-vendor-contact" type="button" data-url="/api/vendors/<?=$vendorId?>/contacts/<?=(int)$contact['id']?>/primary">تعيين كأساسية</button><?php endif;?><button class="btn btn-sm btn-outline-danger js-remove-vendor-contact" type="button" data-url="/api/vendors/<?=$vendorId?>/contacts/<?=(int)$contact['id']?>/remove">حذف</button></div></td><?php endif;?></tr>
<?php endforeach;?></tbody></table></div>
